function deduplicateEnrolments(){let groups=new Map(),removed=new Map();for(let b of db.bookings){let key=(b.studentId||b.student.trim().toLowerCase())+':'+b.classId;let kept=groups.get(key);if(!kept){groups.set(key,b);continue}let winner=b.paid&&!kept.paid?b:kept,duplicate=winner===b?kept:b;groups.set(key,winner);removed.set(duplicate.id,winner.id);let c=cl(duplicate.classId);if(c&&duplicate.status!=='waitlist')c.occupied=Math.max(0,c.occupied-1)}if(!removed.size)return;db.bookings=db.bookings.filter(b=>!removed.has(b.id));for(let r of db.requests){while(removed.has(r.booking))r.booking=removed.get(r.booking)}let current=sessionStorage.getItem('beamal-enrolment');while(removed.has(current))current=removed.get(current);if(current)sessionStorage.setItem('beamal-enrolment',current);save()}
