const lessonsPerBooking=4;
function lessonDatesForClass(c,paidAt){
  if(!c||!validISODate(c.startDate)||!validISODate(c.endDate)||!paidAt)return [];
  const paidMs=Date.parse(/^\d{4}-\d{2}-\d{2}$/.test(paidAt)?`${paidAt}T00:00:00+08:00`:paidAt);
  if(!Number.isFinite(paidMs))return [];
  const paidDay=new Date(paidMs+8*3600000).toISOString().slice(0,10);
  const first=c.startDate>paidDay?c.startDate:paidDay;
  const day=new Date(`${first}T00:00:00Z`),dates=[];
  while(dates.length<lessonsPerBooking){
    const key=day.toISOString().slice(0,10);
    if(key>c.endDate)break;
    if(classDays(c).includes(day.getUTCDay())&&Date.parse(`${key}T${c.time}:00+08:00`)>paidMs)dates.push(key);
    day.setUTCDate(day.getUTCDate()+1);
  }
  return dates;
}
