function nextClassDate(classItem,now=new Date()){if(!validISODate(classItem.startDate)||!validISODate(classItem.endDate))return '';let start=new Date(classItem.startDate+'T00:00:00'),end=new Date(classItem.endDate+'T00:00:00'),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),first=start>today?start:today;for(let offset=0;offset<7;offset++){let candidate=new Date(first);candidate.setDate(first.getDate()+offset);if(candidate>end)return '';if(classDays(classItem).includes(candidate.getDay()))return `${candidate.getFullYear()}-${String(candidate.getMonth()+1).padStart(2,'0')}-${String(candidate.getDate()).padStart(2,'0')}`}return ''}
